import { renderQueue } from "@next2d/render-queue";
/**
 * @description WebGPU用インスタンスシェーダーマネージャー
 */
export class ShaderInstancedManager {
    constructor() {
        Object.defineProperty(this, "count", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.count = 0;
    }
    clear() {
        this.count = renderQueue.offset = 0;
    }
}
